import{_ as e,m as a,n,q as o}from"./chunks/framework.DMDh-7Lg.js";const D=JSON.parse('{"title":"Input Modes","description":"","frontmatter":{},"headers":[],"relativePath":"guides/input-modes.md","filePath":"guides/input-modes.md"}'),l={name:"guides/input-modes.md"};function p(t,s,i,c,r,F){return a(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="input-modes" tabindex="-1">Input Modes <a class="header-anchor" href="#input-modes" aria-label="Permalink to &quot;Input Modes&quot;">​</a></h1><p>Klix supports a small set of input modes through <code>InputMode</code>. They are used by the prompt engine and by higher-level input components.</p><p>For engine details, see <a href="./../concepts/input-engine">Input Engine</a>. For the UI surface, see <a href="./../concepts/ui">UI</a>.</p><h2 id="the-available-modes" tabindex="-1">The Available Modes <a class="header-anchor" href="#the-available-modes" aria-label="Permalink to &quot;The Available Modes&quot;">​</a></h2><p>The enum currently includes:</p><ul><li><code>COMMAND</code></li><li><code>MULTILINE</code></li><li><code>SELECT</code></li><li><code>SEARCH</code></li><li><code>CONFIRM</code></li><li><code>PASSWORD</code></li><li><code>INTERRUPT</code></li></ul><p>These modes influence how the prompt session behaves:</p><ul><li>whether multiline input is allowed</li><li>whether text is masked</li><li>whether a yes/no answer is normalized to boolean</li></ul><h2 id="the-default-app-experience" tabindex="-1">The Default App Experience <a class="header-anchor" href="#the-default-app-experience" aria-label="Permalink to &quot;The Default App Experience&quot;">​</a></h2><p>The standard <code>App.run()</code> loop uses <code>COMMAND</code> mode for each prompt:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">COMMAND</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">raw_input </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">prompt_async</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">&gt; </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>That fits slash-command driven tools well.</p><h2 id="switch-modes-explicitly" tabindex="-1">Switch Modes Explicitly <a class="header-anchor" href="#switch-modes-explicitly" aria-label="Permalink to &quot;Switch Modes Explicitly&quot;">​</a></h2><p>You can change the mode before calling the prompt engine directly:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">COMMAND</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">note </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">prompt_async</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Note: </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>Or let the higher-level helpers do it for you:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">note </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">text</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Note</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">password </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">secret</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Password</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">confirm </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">ui</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">confirm</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Proceed?</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;font-style:italic;"> default</span><span style="color:#89DDFF;">=True)</span></span></code></pre></div><p>Those helpers temporarily select the appropriate mode and manage the prompt details for you.</p><h2 id="multiline-input" tabindex="-1">Multiline Input <a class="header-anchor" href="#multiline-input" aria-label="Permalink to &quot;Multiline Input&quot;">​</a></h2><p>Use <code>MULTILINE</code> when you want a block of text:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">MULTILINE</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">body </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">prompt_async</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Body: </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>In interactive terminals:</p><ul><li><code>Enter</code> submits the full block</li><li><code>Shift+Enter</code> inserts a newline only when the terminal exposes it distinctly</li><li><code>Escape</code> + <code>Enter</code> is the portable newline path Klix supports everywhere</li><li><code>Ctrl+J</code> also inserts a newline in terminals that emit line-feed directly</li></ul><p>In CI or non-interactive mode, the fallback behavior is much simpler and reads a line from standard input.</p><h2 id="confirm-mode" tabindex="-1">Confirm Mode <a class="header-anchor" href="#confirm-mode" aria-label="Permalink to &quot;Confirm Mode&quot;">​</a></h2><p><code>CONFIRM</code> is special because the input engine normalizes the result to a boolean:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">CONFIRM</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">approved </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">prompt_async</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Proceed? [y/n]: </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>That low-level path is what the higher-level confirm component builds on.</p><h2 id="password-mode" tabindex="-1">Password Mode <a class="header-anchor" href="#password-mode" aria-label="Permalink to &quot;Password Mode&quot;">​</a></h2><p><code>PASSWORD</code> masks input through prompt-toolkit:</p><div class="language-python"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#BABED8;">session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set_mode</span><span style="color:#89DDFF;">(</span><span style="color:#82AAFF;">klix</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">InputMode</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">PASSWORD</span><span style="color:#89DDFF;">)</span></span>
<span class="line"><span style="color:#BABED8;">secret </span><span style="color:#89DDFF;">=</span><span style="color:#89DDFF;font-style:italic;"> await</span><span style="color:#BABED8;"> session</span><span style="color:#89DDFF;">.</span><span style="color:#F07178;">input_engine</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">prompt_async</span><span style="color:#89DDFF;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Password: </span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">)</span></span></code></pre></div><p>The higher-level <code>session.ui.input.secret(...)</code> helper also avoids storing the result in input history.</p><h2 id="when-to-use-direct-engine-access" tabindex="-1">When To Use Direct Engine Access <a class="header-anchor" href="#when-to-use-direct-engine-access" aria-label="Permalink to &quot;When To Use Direct Engine Access&quot;">​</a></h2><p>Use the raw engine only when:</p><ul><li>you need a custom prompt flow that the built-in components do not cover</li><li>you are building an example or framework extension</li><li>you want total control over prompt text and mode switching</li></ul><p>For normal app code, prefer <code>session.ui.input.*</code>.</p><h2 id="common-mistakes" tabindex="-1">Common Mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common Mistakes&quot;">​</a></h2><ul><li>Assuming mode switching changes command routing. It only changes prompt behavior; your app loop still decides what input means.</li><li>Expecting multiline editing in CI mode. The fallback path is intentionally simple.</li><li>Forgetting to restore a previous mode if you manage prompt engine state manually in complex code.</li></ul><h2 id="related-reading" tabindex="-1">Related Reading <a class="header-anchor" href="#related-reading" aria-label="Permalink to &quot;Related Reading&quot;">​</a></h2><ul><li><a href="./autocomplete">Autocomplete</a></li><li><a href="./../components/input">Components: Input</a></li><li><a href="./../examples/gemini-style-cli">Examples: Gemini-Style CLI</a></li></ul>`,40)])])}const d=e(l,[["render",p]]);export{D as __pageData,d as default};
